  FT["BN-S-62-2015-E-EMPLOYMENT-AMENDMENT-NO-2-ORDER-2015-1"] = {"id":"BN-S-62-2015-E-EMPLOYMENT-AMENDMENT-NO-2-ORDER-2015-1","coverage":"full","language":"en","sourceName":"Attorney General's Chambers, Brunei Darussalam (AGC) — LAWS OF BRUNEI / Government Gazette","sourceUrl":"","fetchedAt":"2026-10-11","articleCount":2,"structureMode":"SECTION","title":{"zh":"就业第 2 号修正命令 2015(1)","en":"Employment Amendment No 2 Order 2015(1)","orig":"Employment Amendment No 2 Order 2015(1)","vi":"Sắc lệnh sửa đổi Sắc lệnh Việc làm số 2 năm 2015","th":"คำสั่งแก้ไขเพิ่มเติมคำสั่งการจ้างงาน ฉบับที่ 2 พ.ศ. 2558","id":"Perintah Perubahan Perintah Ketenagakerjaan Nomor 2 Tahun 2015","ms":"Perintah Pindaan Perintah Pekerjaan Bilangan 2 2015"},"level":"regulation","status":"active","issuingBody":"Attorney General's Chambers, Brunei Darussalam","completenessNote":"来源为 AGC 官方 PDF《s-62-2015-e-employment-amendment-no-2-order-2015(1).pdf》（3 页），本次切分 2 条。该 PDF 为扫描件 + OCR 文本层，正文按版式位置重建：已剔除页眉页脚与边栏条标题、回接折行；未改写措辞、未增删内容。OCR 层面可能存在个别粘连或形近字，逐字引用请以原始 PDF 为准。","textQuality":"ocr-scanned","sourceFile":"s-62-2015-e-employment-amendment-no-2-order-2015(1).pdf","country":"BN","countryName":"文莱","layer":"intl","articles":[{"id":"BN-S-62-2015-E-EMPLOYMENT-AMENDMENT-NO-2-ORDER-2015-1-A1","no":1,"noLabel":{"en":"Section 1."},"heading":{"en":"Citation"},"text":{"en":"This Order may be cited as the Employment (Amendment) (No. 2) Order, of new section 113A into S 37/2009"}},{"id":"BN-S-62-2015-E-EMPLOYMENT-AMENDMENT-NO-2-ORDER-2015-1-A2","no":2,"noLabel":{"en":"Section 2."},"heading":{"en":"BRUNEI DARUSSALAM GOVERNMENT GAZETTE"},"text":{"en":"The Employment Order, 2009 is amended by inserting the following new immediately after section 113 - \"Medical insurance 113A. (1) The employer shall purchase and maintain medical insurance with coverage of at least $10,000 for a 12 month period of the immigrant employment (or for such shorter period where the immigrant period of employment is less than 12 months) for the immigrant in-patient care and day surgery except as the Commissioner may otherwise provide by notification in writing.\n\n(2) For the purposes of subsection ( 1), where the employer purchases medical insurance policy for his immigrant employees, the employer not be considered to have satisfied the obligation under subsection (1) the terms of the employer's group medical insurance policy are such that each and every individual immigrant employee is concurrently covered to the extent required under that subsection. Any employer who, for the purpose of defraying or partly the cost of insurance in respect of his liability to pay medical under subsection ( 1), makes any deduction from the earnings of an employee employed by him is guilty of an offence and liable on conviction to a fine of $2,000, imprisonment for a term not 6 or both.\n\n(4) Any employer who fails to comply with subsection (1) is guilty of an offence.\". Made this 9th. day of Rabiulawal, 1436 Hijriah corresponding to the 21st. day of December, 2015 at Our Istana Nurul Iman, Bandar Seri Begawan, Brunei Darussalam.\n\nTHE SULTAN AND YANG DI-PERTUAN\n\nBRUNEI DARUSSALAM"}}],"pack":"bn-p31","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1801-BN-1261","source":"Employment Amendment No 2 Order 2015(1)","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["BN-S-63-2000-NOTIFICATION-UNDER-SECTION-11"] = {"id":"BN-S-63-2000-NOTIFICATION-UNDER-SECTION-11","coverage":"full","language":"en","sourceName":"Attorney General's Chambers, Brunei Darussalam (AGC) — LAWS OF BRUNEI / Government Gazette","sourceUrl":"","fetchedAt":"2026-10-11","articleCount":1,"structureMode":"WHOLE","title":{"zh":"依第 11 条发布的公告","en":"NOTIFICATION UNDER SECTION 11","orig":"NOTIFICATION UNDER SECTION 11","vi":"Thông báo theo Điều 11","th":"ประกาศตามมาตรา 11","id":"Pemberitahuan berdasarkan Pasal 11","ms":"Pemberitahuan di bawah Seksyen 11"},"level":"regulation","status":"active","issuingBody":"Attorney General's Chambers, Brunei Darussalam","completenessNote":"来源为 AGC 官方 PDF《S-63_2000_-NOTIFICATION-UNDER-SECTION-11.pdf》（1 页），本次切分 1 条。该 PDF 为扫描件 + OCR 文本层，正文按版式位置重建：已剔除页眉页脚与边栏条标题、回接折行；未改写措辞、未增删内容。OCR 层面可能存在个别粘连或形近字，逐字引用请以原始 PDF 为准。","textQuality":"ocr-scanned","sourceFile":"S-63_2000_-NOTIFICATION-UNDER-SECTION-11.pdf","country":"BN","countryName":"文莱","layer":"intl","articles":[{"id":"BN-S-63-2000-NOTIFICATION-UNDER-SECTION-11-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"24th. JULY, 2000 No. S63\n\nINTERNATIONAL BUSINESS COMPANIES ORDER, 2000 NOTIFICATION UNDER SECTION 1(1) In exercise of the power conferred by section 1 ( 1), the Minister of Finance, with the approval of His Majesty the Sultan and Yang Di-Pertuan, hereby appoints the 1st. July, 2000 as the day on which the International Business Companies Order, 2000 shall commence. Dated this 26th. day of Rabiulawal, 1421 Hijriah corresponding to the 29th. day of June, 2000.\n\nAWANG HAJI ABDUL HAMID BIN HAJI JANUDIN Acting Permanent Secretary, Ministry of Finance, Brunei Darussalam."}}],"pack":"bn-p31","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1801-BN-1261","source":"NOTIFICATION UNDER SECTION 11","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
